CREATE TABLE procurements (procurement_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, procurement_title TEXT NOT NULL, fiscal_year INTEGER NOT NULL CHECK (fiscal_year BETWEEN 2000 AND 2100), issue_date TEXT NOT NULL CHECK (issue_date GLOB '????-??-??'), procurement_status TEXT NOT NULL CHECK (procurement_status IN ('DRAFT','ISSUED','EVALUATION','AWARDED','CANCELLED','CLOSED')), created_at TEXT NOT NULL);

CREATE TABLE awarded_contracts (award_id TEXT PRIMARY KEY, procurement_id TEXT NOT NULL, contract_id TEXT NOT NULL UNIQUE, contractor_id TEXT NOT NULL, contractor_display_name TEXT NOT NULL, executed_amount_cents INTEGER NOT NULL CHECK (executed_amount_cents >= 0), executed_date TEXT NOT NULL CHECK (executed_date GLOB '????-??-??'), award_status TEXT NOT NULL CHECK (award_status IN ('PENDING_EXECUTION','EXECUTED','SUSPENDED','TERMINATED','CLOSED')), created_at TEXT NOT NULL, FOREIGN KEY (procurement_id) REFERENCES procurements(procurement_id));

CREATE TABLE change_order_requests (change_request_id TEXT PRIMARY KEY, award_id TEXT NOT NULL, change_order_number TEXT NOT NULL, request_title TEXT NOT NULL, requested_amount_cents INTEGER NOT NULL, change_status TEXT NOT NULL CHECK (change_status IN ('DRAFT','SUBMITTED','UNDER_REVIEW','RETURNED','REJECTED','WITHDRAWN','EXECUTED')), requested_date TEXT NOT NULL CHECK (requested_date GLOB '????-??-??'), executed_date TEXT CHECK (executed_date IS NULL OR executed_date GLOB '????-??-??'), billing_reference TEXT, created_at TEXT NOT NULL, UNIQUE (award_id, change_order_number), CHECK (change_status <> 'EXECUTED' OR executed_date IS NOT NULL), FOREIGN KEY (award_id) REFERENCES awarded_contracts(award_id));

CREATE TABLE approval_actions (approval_action_id TEXT PRIMARY KEY, change_request_id TEXT, award_id TEXT NOT NULL, approver_id TEXT NOT NULL, approver_role TEXT NOT NULL, action_code TEXT NOT NULL CHECK (action_code IN ('SUBMIT','APPROVE','REJECT','RETURN','WITHDRAW','COMMENT')), action_timestamp TEXT NOT NULL, action_comment TEXT, FOREIGN KEY (change_request_id) REFERENCES change_order_requests(change_request_id), FOREIGN KEY (award_id) REFERENCES awarded_contracts(award_id));

CREATE TABLE billing_control_rules (control_rule_id TEXT PRIMARY KEY, procurement_id TEXT, award_id TEXT, rule_code TEXT NOT NULL, rule_name TEXT NOT NULL, rule_value TEXT NOT NULL, effective_date TEXT NOT NULL CHECK (effective_date GLOB '????-??-??'), expiration_date TEXT CHECK (expiration_date IS NULL OR expiration_date GLOB '????-??-??'), active_flag INTEGER NOT NULL CHECK (active_flag IN (0,1)), source_document_ref TEXT NOT NULL, CHECK (procurement_id IS NOT NULL OR award_id IS NOT NULL), FOREIGN KEY (procurement_id) REFERENCES procurements(procurement_id), FOREIGN KEY (award_id) REFERENCES awarded_contracts(award_id));